{
  "references": [
    {
      "id": "R1",
      "summary_ko": "손에 쥐고 있던 유리잔이 사라지고 대체 물체 없이 닦는 동안 빈 손 상태로 유지됨.",
      "claims": [
        {
          "id": "R1.S1",
          "evidence": "The glass in her hand disappears",
          "symptom_ko": "손에 있던 유리잔이 사라짐",
          "role": "complaint"
        },
        {
          "id": "R1.S2",
          "evidence": "no replacement object appears and her hand stays empty throughout wiping",
          "symptom_ko": "대체 물체가 나타나지 않고 닦는 내내 손이 빈 상태로 유지됨",
          "role": "complaint"
        }
      ]
    }
  ],
  "candidates": [
    {
      "id": "C1",
      "summary_ko": "유리잔이 닦는 동안 손에 들려 있는 천으로 변함.",
      "target_evidence": "The glass",
      "interaction_evidence": "stays visibly held in her hand throughout wiping",
      "change_evidence": "becomes a cloth",
      "scope": "individual"
    }
  ],
  "pairs": [
    {
      "reference_id": "R1",
      "candidate_id": "C1",
      "target_relation": "same_interaction",
      "event_relation": "different",
      "description_consistency": "core_conflict",
      "conflict_scope": "matched_claim",
      "reference_claim_ids": [
        "R1.S1",
        "R1.S2"
      ],
      "reference_evidence": "no replacement object appears and her hand stays empty throughout wiping",
      "candidate_evidence": "The glass becomes a cloth that stays visibly held in her hand throughout wiping.",
      "shared_event_ko": "손에 들고 있던 유리잔이 닦는 과정에서 변하는 현상에 대한 서술.",
      "coexistence_explanation_ko": "",
      "conflicts_ko": [
        "레퍼런스는 대체 물체 없이 손이 비어 있다고 명시했으나, 후보는 유리잔이 천으로 바뀌어 손에 계속 쥐어져 있다고 주장하여 정면으로 충돌함"
      ],
      "reason_ko": "레퍼런스는 대체 물체가 나타나지 않고 손이 비어 있다고 주장한 반면, 후보는 유리잔이 천으로 변하여 손에 계속 쥐어져 있다고 서술하여 동일한 상호작용 상황에서 상호 배타적인 주장을 하고 있습니다.",
      "event_link": "distinct_events",
      "separation_basis": "contradictory_claim"
    }
  ]
}

{
  "pairs": [
    {
      "reference_id": "R1",
